// Capture the daemon entry's observable behaviour from a BUILT checkout.
// Usage: node capture-goldens.mjs <repo-root-with-built-apps/syzygy>
import { spawn, spawnSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, writeFileSync, readdirSync, statSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import * as path from 'node:path';

const repo = path.resolve(process.argv[2]);
const entry = path.join(repo, 'apps', 'syzygy', 'dist', 'main.js');
const env = Object.fromEntries(Object.entries(process.env).filter(([k]) => !k.startsWith('SYZYGY_')));

function fixture(root) {
  mkdirSync(path.join(root, '.syzygy', 'governance', 'decisions'), { recursive: true });
  mkdirSync(path.join(root, '.syzygy', 'intent'), { recursive: true });
  mkdirSync(path.join(root, 'openspec'), { recursive: true });
  writeFileSync(path.join(root, 'README.md'), '# fixture readme\n');
}
function sweep(dir, base = dir) {
  const out = [];
  for (const name of readdirSync(dir).sort()) {
    const p = path.join(dir, name); const s = statSync(p);
    const rel = path.relative(base, p);
    out.push(`${s.isDirectory() ? 'd' : 'f'} ${(s.mode & 0o777).toString(8)} ${rel}`);
    if (s.isDirectory()) out.push(...sweep(p, base));
  }
  return out;
}
const mask = (t, map) => {
  for (const [k, v] of map) t = t.split(k).join(v);
  return t.replace(/127\.0\.0\.1:\d+/g, '127.0.0.1:<PORT>');
};
const results = {};
function sync(name, args, cwd) {
  const r = spawnSync(process.execPath, [entry, ...args], { cwd, env, encoding: 'utf8' });
  results[name] = { args, status: r.status, stdout: mask(r.stdout, [[cwd, '<BASE>']]), stderr: mask(r.stderr, [[cwd, '<BASE>']]) };
}
const base = mkdtempSync(path.join(tmpdir(), 'syz-golden-'));
const root = path.join(base, 'root'); fixture(root);
sync('help', ['--help'], base);
sync('help-short', ['-h'], base);
sync('dossier', ['dossier'], base);
sync('dossier-status', ['dossier', 'status', 'x'], base);
sync('unknown-flag', ['--bogus'], base);
sync('help-then-dossier', ['--help', 'dossier'], base);
sync('dossier-not-first', ['--port', '0', 'dossier'], base);
sync('dossier-uppercase', ['Dossier'], base);
sync('port-missing-value', ['--port'], base);
sync('port-out-of-range', ['--port', '70000'], base);
sync('state-in-governed', ['--root', root, '--state-dir', path.join(root, '.syzygy', 'x')], base);

async function run(name, args, cwd, extraEnv, stateDir) {
  const child = spawn(process.execPath, [entry, ...args], { cwd, env: { ...env, ...extraEnv }, stdio: ['ignore', 'pipe', 'pipe'] });
  let out = '', err = '';
  child.stdout.setEncoding('utf8').on('data', (c) => (out += c));
  child.stderr.setEncoding('utf8').on('data', (c) => (err += c));
  const exited = new Promise((r) => child.once('exit', r));
  const deadline = Date.now() + 30000;
  while (!/listening at http:\/\/127\.0\.0\.1:\d+\//.test(out)) {
    if (Date.now() > deadline) throw new Error(`no announce: ${out}\n${err}`);
    await new Promise((r) => setTimeout(r, 50));
  }
  const port = /127\.0\.0\.1:(\d+)/.exec(out)[1];
  const status = (await fetch(`http://127.0.0.1:${port}/`)).status;
  const whileRunning = sweep(stateDir);
  child.kill('SIGINT');
  const code = await exited;
  results[name] = { args, env: extraEnv, rootStatus: status, exit: code,
    stdout: mask(out, [[stateDir, '<STATE>'], [cwd, '<CWD>']]), stderr: mask(err, [[stateDir, '<STATE>'], [cwd, '<CWD>']]),
    stateWhileRunning: whileRunning, stateAfterExit: sweep(stateDir) };
}
await run('no-arguments', [], root, { SYZYGY_PORT: '0' }, path.join(root, '.syzygy-daemon-state'));
const sd = path.join(base, 'state');
await run('explicit-flags', ['--root', root, '--state-dir', sd, '--port', '0'], base, {}, sd);
rmSync(base, { recursive: true, force: true });
process.stdout.write(JSON.stringify({ repoHead: spawnSync('git', ['-C', repo, 'rev-parse', 'HEAD'], { encoding: 'utf8' }).stdout.trim(), results }, null, 2) + '\n');
